// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address actor, uint256 tokenId) public {
        uint256 id = tokenId % 50;

        vm.assume(actor != address(0));

        uint256 existing = c.uniqueTokensOutstanding();
        if (existing <= id + 1) {
            for (uint256 i = existing; i < id + 2; ++i) {
                c.createGameItem("name", "uri", false, true, 1000, 1, 10);
            }
        }

        StubNeuron nrn = new StubNeuron();
        c.instantiateNeuronContract(address(nrn));

        nrn.setBalance(actor, 1000);

        vm.prank(actor);
        c.mint(id, 5);

        vm.prank(actor);
        c.mint(id + 1, 7);

        uint256 b = c.balanceOf(actor, id);
        assertTrue(b == 5);
    }
}

contract StubNeuron {
    mapping(address => uint256) public balances;
    mapping(address => mapping(address => uint256)) public allowances;

    function setBalance(address who, uint256 amt) external {
        balances[who] = amt;
    }

    function balanceOf(address who) external view returns (uint256) {
        return balances[who];
    }

    function approveSpender(address account, uint256 amount) external {
        allowances[account][msg.sender] = amount;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (allowances[from][msg.sender] >= amount) {
            if (balances[from] < amount) return false;
            balances[from] -= amount;
            balances[to] += amount;
            return true;
        }
        return false;
    }
}
